#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
stage=$(mktemp "$base/.deliver.XXXXXXXXXX")
trap 'rm -f "$stage"' EXIT HUP INT TERM

cat > "$stage"

department=$(
    awk '
        BEGIN { value = "" }
        /^\r?$/ { exit }
        {
            line = $0
            sub(/\r$/, "", line)
            colon = index(line, ":")
            if (colon > 0) {
                name = substr(line, 1, colon - 1)
                if (tolower(name) == "x-department") {
                    value = substr(line, colon + 1)
                    sub(/^[[:space:]]+/, "", value)
                    sub(/[[:space:]]+$/, "", value)
                    print tolower(value)
                    exit
                }
            }
        }
    ' "$stage"
)

case "$department" in
    accounts) mailbox=accounts ;;
    support)  mailbox=support ;;
    *)        mailbox=general ;;
esac

destination="$base/Maildir/$mailbox/new"
mkdir -p "$destination"
target=$(mktemp "$destination/$(date +%s).XXXXXXXXXX.$(hostname)")
mv "$stage" "$target"
trap - EXIT HUP INT TERM
ANTRIEB_DELIVER_EOF
chmod 0755 /srv/legacy2/mail-filter-routing/bin/deliver
